const f = $input.first().json;
const nome = f.name || '';
const base = nome.replace(/\.[a-z0-9]+$/i, '');
const busca = base.replace(/[-_0-9]+/g, ' ').replace(/\s+/g, ' ').trim();

return [{ json: {
  file_id: f.id,
  arquivo: nome,
  mimeType: f.mimeType || '',
  video: /\.(mp4|mov)$/i.test(nome),
  busca
} }];

