const ia = $input.first().json.output || $input.first().json;
const arq = $('Dados do arquivo').first().json;

const legendaCompleta = [ia.gancho, '', ia.legenda].join('\n');

return [{ json: {
  id: 'auto-' + Date.now(),
  data: '',
  hora: '',
  tipo: arq.video ? 'feed' : 'story',
  formato: arq.video ? 'Reels' : 'Story',
  produto: ia.produto || '',
  categoria: ia.categoria || '',
  arquivo: arq.arquivo,
  link: ia.link || '',
  legenda: legendaCompleta,
  hashtags: ia.hashtags || '',
  status: 'A PROGRAMAR',
  post_id: '',
  postado_em: '',
  narracao: ia.narracao || ''
} }];
